import PropTypes from "prop-types";
// @mui
import { useTheme } from "@mui/material/styles";
import {
  Box,
  Card,
  Chip,
  Grid,
  Stack,
  Divider,
  Typography,
} from "@mui/material";
// utils
import { fDateTime } from "../../../../utils/formatTime";
import { fCurrency } from "../../../../utils/formatNumber";
// components
import Label from "../../../../components/Label";
import Image from "../../../../components/Image";
import { useTranslation } from "react-i18next";

// ----------------------------------------------------------------------

TicketDetails.propTypes = {
  ticket: PropTypes.object,
};

const appCurrency = localStorage.getItem("app-currency") || "CLP";

function renderValue(value, t) {
  if (value === null || value === undefined || value === "") {
    return "-";
  }

  if (Array.isArray(value)) {
    return value.join(", ");
  }

  if (typeof value === "boolean") {
    return value ? t("params.yes") : t("params.no");
  }

  return String(value);
}

function InfoBlock({ label, value }) {
  return (
    <Box
      sx={{
        p: 2,
        borderRadius: 2,
        bgcolor: "grey.100",
        height: "100%",
      }}
    >
      <Typography variant="caption" sx={{ color: "text.secondary" }}>
        {label}
      </Typography>
      <Typography variant="subtitle1" sx={{ mt: 0.75, wordBreak: "break-word" }}>
        {value}
      </Typography>
    </Box>
  );
}

InfoBlock.propTypes = {
  label: PropTypes.string.isRequired,
  value: PropTypes.node.isRequired,
};

function NumberList({ title, values, color = "default", t }) {
  if (!values?.length) {
    return null;
  }

  return (
    <Box>
      <Typography variant="subtitle2" sx={{ mb: 1.5 }}>
        {title}
      </Typography>
      <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">
        {values.map((value, index) => (
          <Chip key={`${title}-${index}-${value}`} label={renderValue(value, t)} color={color} variant="outlined" />
        ))}
      </Stack>
    </Box>
  );
}

NumberList.propTypes = {
  title: PropTypes.string.isRequired,
  values: PropTypes.array,
  color: PropTypes.string,
  t: PropTypes.func.isRequired,
};

function formatBorletteBoule(boule, lotto, option = "") {
  const raw = String(boule || "");
  const type = String(lotto || "");
  const opt = String(option || "");

  if (type === "MA") return `${raw.slice(0, 2)}*${raw.slice(2)}`;
  if (type === "L3B") return `${raw}B`;
  if (type === "L4") return opt === "5" ? raw : `${raw} (${opt})`;
  if (type === "L5") return `${raw} (${opt})`;
  if (type === "L4B") return `${raw}B`;
  if (type === "P2" || type === "P5") return `${raw}P`;
  return raw;
}

function getBorletteLottoLabel(t, lotto) {
  const labels = {
    BO: t("ticket_details.lotto_bo"),
    P2: t("ticket_details.lotto_p2"),
    P5: t("ticket_details.lotto_p5"),
    L3: t("ticket_details.lotto_l3"),
    L3B: t("ticket_details.lotto_l3b"),
    MA: t("ticket_details.lotto_ma"),
    L4: t("ticket_details.lotto_l4"),
    L4B: t("ticket_details.lotto_l4b"),
    L5: t("ticket_details.lotto_l5"),
  };

  return labels[lotto] || lotto || "-";
}

function renderPlayDetails(ticket, t) {
  const details = ticket?.play_details;

  if (!details) {
    return (
      <Typography variant="body2" sx={{ color: "text.secondary" }}>
        {t("ticket_details.no_play_details")}
      </Typography>
    );
  }

  if (details.type === "borlette") {
    return (
      <Stack spacing={1.25}>
        {details.tirage ? (
          <Box sx={{ mb: 1 }}>
            <InfoBlock label={t("params.tirage")} value={details.tirage} />
          </Box>
        ) : null}
        {(details.lines || []).map((line, index) => (
          <Box
            key={`borlette-line-${index}`}
            sx={{
              p: 1.5,
              borderRadius: 2,
              border: (theme) => `1px solid ${theme.palette.divider}`,
              bgcolor: "background.paper",
            }}
          >
            <Stack
              direction={{ xs: "column", sm: "row" }}
              spacing={1.25}
              alignItems={{ xs: "flex-start", sm: "center" }}
              justifyContent="space-between"
            >
              <Stack
                direction="row"
                spacing={1}
                alignItems="center"
                flexWrap="wrap"
                useFlexGap
              >
                <Chip
                  label={formatBorletteBoule(line?.boule, line?.lotto, line?.option)}
                  color="info"
                  sx={{
                    fontWeight: 700,
                    color: "common.white",
                    background: (theme) =>
                      `linear-gradient(135deg, ${theme.palette.info.light}, ${theme.palette.info.dark})`,
                  }}
                />
                <Typography variant="body2" sx={{ color: "text.secondary" }}>
                  {`${getBorletteLottoLabel(t, String(line?.lotto || ""))} • ${t("ticket_details.mise")}: ${fCurrency(
                    Number(line?.montant || 0)
                  )} ${appCurrency}`}
                </Typography>
              </Stack>
              <Typography variant="caption" sx={{ color: "text.secondary" }}>
                {t("ticket_details.play_number", { number: index + 1 })}
              </Typography>
            </Stack>
          </Box>
        ))}
      </Stack>
    );
  }

  if (details.type === "keno") {
    return (
      <Stack spacing={3}>
        <NumberList title={t("ticket_details.selected_numbers")} values={details.selected_numbers} color="primary" t={t} />
        <NumberList title={t("ticket_details.winning_numbers")} values={details.winning_numbers} color="success" t={t} />
      </Stack>
    );
  }

  if (details.type === "roulette") {
    return (
      <Stack spacing={3}>
        <NumberList title={t("ticket_details.selected_numbers")} values={details.selected_numbers} color="primary" t={t} />
        <InfoBlock label={t("ticket_details.winning_number")} value={renderValue(details.winning_number, t)} />
      </Stack>
    );
  }

  if (details.type === "luckysix") {
    return (
      <Stack spacing={3}>
        <Grid container spacing={2}>
          <Grid item xs={12} md={4}>
            <InfoBlock label={t("ticket_details.type_bet")} value={renderValue(details.type_bet, t)} />
          </Grid>
          <Grid item xs={12} md={4}>
            <InfoBlock label={t("ticket_details.special")} value={renderValue(details.special, t)} />
          </Grid>
          <Grid item xs={12} md={4}>
            <InfoBlock label={t("ticket_details.side")} value={renderValue(details.side, t)} />
          </Grid>
        </Grid>
        <NumberList title={t("ticket_details.selected_numbers")} values={details.selected_numbers} color="primary" t={t} />
        <NumberList title={t("ticket_details.selected_colors")} values={details.selected_colors} color="warning" t={t} />
        <NumberList title={t("ticket_details.winning_numbers")} values={details.winning_numbers} color="success" t={t} />
        <NumberList title={t("ticket_details.bonus_numbers")} values={details.bonus_numbers} color="secondary" t={t} />
      </Stack>
    );
  }

  if (details.type === "horse") {
    return (
      <Stack spacing={3}>
        {details.horse_win ? (
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <InfoBlock label={t("ticket_details.horse_winner")} value={renderValue(details.horse_win.name, t)} />
            </Grid>
            <Grid item xs={12} md={4}>
              <InfoBlock label={t("ticket_details.winner_number")} value={renderValue(details.horse_win.number, t)} />
            </Grid>
            <Grid item xs={12} md={4}>
              <InfoBlock label={t("ticket_details.winner_odds")} value={renderValue(details.horse_win.odds, t)} />
            </Grid>
          </Grid>
        ) : null}
        <Grid container spacing={2}>
          {(details.horses_bets || []).map((bet, index) => (
            <Grid item xs={12} md={6} key={`horse-bet-${index}`}>
              <Card variant="outlined" sx={{ p: 2 }}>
                <Stack spacing={1}>
                  <Typography variant="subtitle2">{t("ticket_details.horse_number", { number: renderValue(bet?.number, t) })}</Typography>
                  <Typography variant="body2">{renderValue(bet?.name, t)}</Typography>
                  <Typography variant="body2">{t("ticket_details.coeff")}: {renderValue(bet?.coeff, t)}</Typography>
                  <Typography variant="body2">
                    {t("ticket_details.value")}: {fCurrency(Number(bet?.value || 0))} {appCurrency}
                  </Typography>
                  <Typography variant="body2">
                    {t("ticket_details.prize")}: {fCurrency(Number(bet?.prize || 0))} {appCurrency}
                  </Typography>
                </Stack>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Stack>
    );
  }

  if (details.type === "raf") {
    return (
      <Stack spacing={3}>
        <InfoBlock label={t("ticket_details.round_code")} value={renderValue(details.round_code, t)} />
        <NumberList title={t("ticket_details.selected_numbers")} values={details.numbers} color="primary" t={t} />
      </Stack>
    );
  }

  if (details.type === "slot") {
    const patternRows = Array.isArray(details.pattern)
      ? details.pattern.map((row) => (Array.isArray(row) ? row.join(" | ") : renderValue(row)))
      : [];

    return (
      <Stack spacing={3}>
        <Grid container spacing={2}>
          <Grid item xs={12} md={4}>
            <InfoBlock label={t("ticket_details.freespin")} value={renderValue(details.freespin, t)} />
          </Grid>
          <Grid item xs={12} md={4}>
            <InfoBlock label={t("ticket_details.number_freespin")} value={renderValue(details.num_freespin, t)} />
          </Grid>
          <Grid item xs={12} md={4}>
            <InfoBlock label={t("ticket_details.bonus")} value={renderValue(details.bonus, t)} />
          </Grid>
        </Grid>
        {patternRows.length ? (
          <Card variant="outlined" sx={{ p: 2 }}>
            <Typography variant="subtitle2" sx={{ mb: 1.5 }}>
              {t("ticket_details.pattern")}
            </Typography>
            <Stack spacing={1}>
              {patternRows.map((row, index) => (
                <Typography variant="body2" key={`pattern-row-${index}`}>
                  {row}
                </Typography>
              ))}
            </Stack>
          </Card>
        ) : null}
        <Card variant="outlined" sx={{ p: 2 }}>
          <Typography variant="subtitle2" sx={{ mb: 1.5 }}>
            {t("ticket_details.win_lines")}
          </Typography>
          <Typography variant="body2" sx={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
            {JSON.stringify(details.win_lines || [], null, 2)}
          </Typography>
        </Card>
      </Stack>
    );
  }

  return (
    <Card variant="outlined" sx={{ p: 2 }}>
      <Typography variant="subtitle2" sx={{ mb: 1.5 }}>
        {t("ticket_details.raw_play_data")}
      </Typography>
      <Typography variant="body2" sx={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
        {JSON.stringify(details.raw_boules || details, null, 2)}
      </Typography>
    </Card>
  );
}

export default function TicketDetails({ ticket }) {
  const theme = useTheme();
  const { t } = useTranslation();

  if (!ticket) {
    return null;
  }

  return (
    <Stack spacing={3}>
      <Card sx={{ p: 3 }}>
        <Stack
          direction={{ xs: "column", sm: "row" }}
          justifyContent="space-between"
          spacing={2}
          sx={{ mb: 3 }}
        >
          <Image
            disabledEffect
            visibleByDefault
            src="/static/logo/logo.png"
            alt="logo"
            sx={{ maxWidth: 120 }}
          />
          <Stack alignItems={{ xs: "flex-start", sm: "flex-end" }} spacing={1}>
            <Typography variant="h5">{ticket.ref_code}</Typography>
            <Stack direction="row" spacing={1}>
              <Label
                variant={theme.palette.mode === "light" ? "ghost" : "filled"}
                color={
                  (ticket.status === "WIN" && "success") ||
                  (ticket.status === "PENDING" && "warning") ||
                  (ticket.status === "WRONG" && "error") ||
                  "default"
                }
                sx={{ textTransform: "uppercase" }}
              >
                {ticket.status}
              </Label>
              {ticket.status === "WIN" ? (
                <Label
                  variant={theme.palette.mode === "light" ? "ghost" : "filled"}
                  color={ticket.paid === "PAID" ? "success" : "info"}
                  sx={{ textTransform: "uppercase" }}
                >
                  {ticket.paid}
                </Label>
              ) : null}
            </Stack>
          </Stack>
        </Stack>

        <Grid container spacing={2}>
          <Grid item xs={12} md={3}>
            <InfoBlock label={t("ticket_details.client_vendor")} value={ticket.vendor_name || "-"} />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock label={t("field.game")} value={ticket.game_name || "-"} />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock label={t("field.date")} value={fDateTime(ticket.created_on)} />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock label={t("params.tirage")} value={ticket.tirage_display || "-"} />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock label={t("ticket_details.mise")} value={`${fCurrency(Number(ticket.mise || 0))} ${appCurrency}`} />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock label={t("field.win")} value={`${fCurrency(Number(ticket.gain || 0))} ${appCurrency}`} />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock
              label={t("ticket_details.commission_ag")}
              value={`${fCurrency(Number(ticket.commission_ag || 0))} ${appCurrency}`}
            />
          </Grid>
          <Grid item xs={12} md={3}>
            <InfoBlock
              label={t("ticket_details.commission_sp")}
              value={`${fCurrency(Number(ticket.commission_sp || 0))} ${appCurrency}`}
            />
          </Grid>
        </Grid>
      </Card>

      <Card sx={{ p: 3 }}>
        <Typography variant="h6">{t("ticket_details.client_game")}</Typography>
        <Typography variant="body2" sx={{ color: "text.secondary", mb: 3 }}>
          {t("ticket_details.client_game_desc")}
        </Typography>
        {renderPlayDetails(ticket, t)}
      </Card>

      <Divider />
    </Stack>
  );
}
